
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_b97_3c_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_b97_3c", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.499494534910006e+00, -4.409273918163154e+00, -4.282933832194323e+00, -4.108099866349946e+00, -3.870274100605110e+00, -3.554725724052622e+00, -3.151106898420728e+00, -2.662630185969898e+00, -2.121708817811899e+00, -1.602428802020289e+00, -1.125870762005854e+00, -7.668748357306214e-01, -6.578876342967395e-01, -5.393735225735362e-01, -3.869867764599457e-01, -2.409565828492682e-01, -1.695366201953647e-01, -9.231902609974647e-02, -2.358406461531816e-02, -2.847221899466746e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


